using System.Collections.Frozen;
using System.Text.Json;

namespace CaseIntake.VeteranLookup.Mock;

/// <summary>
/// The deterministic synthetic dataset, loaded once from the embedded <c>veterans.json</c> (generated by
/// <c>VeteranDatasetGenerator</c> in the test project and guarded there by a drift test). Every SSN has an area
/// number of 900-999, a range the SSA never issues, so no fixture can belong to a real person.
/// </summary>
public sealed class VeteranDataset
{
    public const string ResourceName = "CaseIntake.VeteranLookup.Mock.veterans.json";

    private readonly FrozenDictionary<string, VeteranRecord> _bySsn;

    public VeteranDataset(IEnumerable<VeteranRecord> records)
    {
        ArgumentNullException.ThrowIfNull(records);
        Records = [.. records];
        _bySsn = Records.ToFrozenDictionary(r => r.Ssn, StringComparer.Ordinal);
    }

    public IReadOnlyList<VeteranRecord> Records { get; }

    public static VeteranDataset LoadEmbedded()
    {
        using var stream = typeof(VeteranDataset).Assembly.GetManifestResourceStream(ResourceName)
            ?? throw new InvalidOperationException($"Embedded resource {ResourceName} is missing.");
        var records = JsonSerializer.Deserialize(stream, MockJsonContext.Default.VeteranRecordArray)
            ?? throw new InvalidOperationException("The veteran dataset is empty.");
        return new VeteranDataset(records);
    }

    /// <summary>Finds a veteran by SSN in either the dashed (<c>NNN-NN-NNNN</c>) or the nine-digit form.</summary>
    public bool TryFind(string ssn, out VeteranRecord record)
    {
        ArgumentNullException.ThrowIfNull(ssn);
        var key = ssn.Length == 9 && ssn.All(char.IsAsciiDigit) ? $"{ssn[..3]}-{ssn[3..5]}-{ssn[5..]}" : ssn;
        return _bySsn.TryGetValue(key, out record!);
    }
}
